third_iso.{u_2} {G : Type u_2} [AddCommGroup G] {G₂ : AddSubgroup G} (H' : AddSubgroup (G ⧸ G₂)) :
  let H := G ⧸ G₂;
  have φ := QuotientAddGroup.mk' G₂;
  let N := AddSubgroup.comap φ H';
  ∃ e, ∀ (x : G), e ((QuotientAddGroup.mk' H') (φ x)) = (QuotientAddGroup.mk' N) x
